      { t = "accept", id = { 8460, 5155, 5156 }, quest = "Timbermaw Ally + Forces of Jaedenar + Verifying the Corruption", lvl = 54, req = 48, zone = "Felwood", m = 1448, x = 50.9, y = 85, text = "Grazle : Descends au sud jusqu'à Emerald Sanctuary : Timbermaw Ally, Forces of Jaedenar et Verifying the Corruption.", en = "Grazle: Ride south to Emerald Sanctuary: Timbermaw Ally, Forces of Jaedenar and Verifying the Corruption." },
      { t = "do", id = { 8460, 6162 }, quest = "Timbermaw Ally + A Husband's Last Battle", lvl = 51, zone = "Felwood", m = 1448, x = 48.1, y = 90.9, text = "Plus au sud : 6 Deadwood Warriors, 6 Pathfinders, 6 Gardeners (furbolgs), et la griffe d'Overlord Ror.", en = "Further south: 6 Deadwood Warriors, 6 Pathfinders, 6 Gardeners (furbolgs), and Overlord Ror's claw." },
