      { t = "do", id = 5155, quest = "Forces of Jaedenar", lvl = 51, zone = "Felwood", m = 1448, x = 37.3, y = 60.8, text = "Jaedenar (ouest) : 4 Hounds, 4 Guardians, 6 Adepts et 6 Cultists.", en = "Jaedenar (west): 4 Hounds, 4 Guardians, 6 Adepts and 6 Cultists." },
      { t = "turnin", id = 5155, quest = "Forces of Jaedenar", lvl = 51, zone = "Felwood", m = 1448, x = 51.2, y = 82.1, text = "Greta Mosshoof : Emerald Sanctuary.", en = "Greta Mosshoof: Emerald Sanctuary." },
      { t = "accept", id = 5157, quest = "Collection of the Corrupt Water", lvl = 52, req = 48, pre = { 5155 }, zone = "Felwood", m = 1448, x = 51.2, y = 82.1, text = "Collection of the Corrupt Water (Greta Mosshoof : la gourde vide).", en = "Collection of the Corrupt Water (Greta Mosshoof: the empty canteen)." },
