  steppes = {
    title = "Burning Steppes & Blasted Lands 50-54",
    title_en = "Burning Steppes & Blasted Lands 50-54",
    races = { "Orc", "Troll", "Tauren", "Scourge" },
    steps = {
      { t = "note", text = "Guide Burning Steppes & Blasted Lands (50-54). Route : Undercity, Kargath, Searing Gorge (chaîne de Kalaran Windblade), Burning Steppes, puis à cheval jusqu'à Stonard et les Blasted Lands. Retour par Kargath pour les quêtes de niveau 52.", en = "Burning Steppes & Blasted Lands guide (50-54). Route: Undercity, Kargath, Searing Gorge (Kalaran Windblade's chain), Burning Steppes, then a ride to Stonard and the Blasted Lands. Back through Kargath for the level 52 quests." },
      { t = "note", text = "Avertissement PvP (risque élevé) : Thorium Point (partagé), l'entrée de Blackrock Mountain et Morgan's Vigil (Alliance) ; Lakeshire et Darkshire sur la route de Stonard ; Nethergarde dans les Blasted Lands. Reste près des gardes, garde ta pierre de foyer prête, et évite de te battre près des points chauds.", en = "PvP warning (high risk): Thorium Point (shared), the Blackrock Mountain entrance and Morgan's Vigil (Alliance); Lakeshire and Darkshire on the way to Stonard; Nethergarde in the Blasted Lands. Stay near the guards, keep your hearthstone ready, and avoid fighting near the hotspots." },
      { t = "level", level = 49, text = "Niveau 49 conseillé pour cette zone. Si tu es en dessous, tue des monstres en chemin ou fais un donjon.", en = "Level 49 recommended for this zone. If you are below it, kill mobs on the way or run a dungeon." },
      { t = "go", zone = "Undercity", m = 1458, x = 66.5, y = 38.5, text = "Arret à Undercity (tu y passes de toute facon) : entraineur de classe, hotel des ventes et banque (le Trade Quarter), reparations. Rends les deux vases à l'Apothecarium.", en = "Stop in Undercity (you pass through anyway): class trainer, auction house and bank (the Trade Quarter), repairs. Turn in both oozes at the Apothecarium." },
      { t = "turnin", id = { 4294, 4293 }, quest = "... and a Batch of Ooze + A Sample of Slime...", lvl = 56, optional = true, zone = "Undercity", m = 1458, x = 47.5, y = 73.3, text = "Chemist Fuely : Undercity, Apothecarium : ... and a Batch of Ooze et A Sample of Slime....", en = "Chemist Fuely: Undercity, Apothecarium: ... and a Batch of Ooze and A Sample of Slime...." },
      { t = "accept", id = 3821, quest = "Dreadmaul Rock", lvl = 52, req = 48, zone = "Badlands", m = 1418, x = 3.4, y = 48.1, text = "Thal'trak Proudtusk : Vole vers Kargath (Badlands) : Dreadmaul Rock — 40 m au sud de l'auberge.", en = "Thal'trak Proudtusk: Fly to Kargath (Badlands): Dreadmaul Rock — 40 m south of the inn." },
      { t = "accept", id = 3441, quest = "Divine Retribution", lvl = 48, req = 40, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade : Vole de Kargath vers Thorium Point, puis descends un peu au sud : Divine Retribution.", en = "Kalaran Windblade: Fly from Kargath to Thorium Point, then ride a little south: Divine Retribution." },
      { t = "do", id = 3441, quest = "Divine Retribution", lvl = 48, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Écoute l'histoire de Kalaran jusqu'au bout.", en = "Listen to Kalaran's story to the end." },
      { t = "turnin", id = 3441, quest = "Divine Retribution", lvl = 48, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade.", en = "Kalaran Windblade." },
      { t = "accept", id = 3442, quest = "The Flawless Flame", lvl = 48, req = 40, pre = { 3441 }, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade : The Flawless Flame.", en = "Kalaran Windblade: The Flawless Flame." },
      { t = "do", id = 3442, quest = "The Flawless Flame", lvl = 48, zone = "Searing Gorge", m = 1427, x = 53.8, y = 47.2, text = "Centre-est : 4 Hearts of Flame sur les élémentaires (Magma, Blazing, Inferno) et 4 Golem Oil sur les golems (Heavy et Tempered War Golems).", en = "East-centre: 4 Hearts of Flame from the elementals (Magma, Blazing, Inferno) and 4 Golem Oil from the golems (Heavy and Tempered War Golems)." },
      { t = "turnin", id = 3442, quest = "The Flawless Flame", lvl = 48, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade.", en = "Kalaran Windblade." },
      { t = "accept", id = 3443, quest = "Forging the Shaft", lvl = 48, req = 40, pre = { 3442 }, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade : Forging the Shaft.", en = "Kalaran Windblade: Forging the Shaft." },
      { t = "do", id = 3443, quest = "Forging the Shaft", lvl = 48, zone = "Searing Gorge", m = 1427, x = 40.6, y = 36.1, text = "Juste au nord-est (The Cauldron) : 8 Thorium Plated Daggers sur les nains Dark Iron.", en = "Just northeast (The Cauldron): 8 Thorium Plated Daggers from the Dark Iron dwarves." },
      { t = "turnin", id = 3443, quest = "Forging the Shaft", lvl = 48, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade.", en = "Kalaran Windblade." },
      { t = "accept", id = 3452, quest = "The Flame's Casing", lvl = 50, req = 40, pre = { 3443 }, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade : The Flame's Casing.", en = "Kalaran Windblade: The Flame's Casing." },
      { t = "do", id = 3452, quest = "The Flame's Casing", lvl = 50, zone = "Searing Gorge", m = 1427, x = 19.8, y = 38, text = "Blackchar Cave (ouest) : 1 Symbol of Ragnaros sur les cultistes Twilight. Les Twilight Fire Guards sont élites et des Flamebringers (55-60) rôdent autour : tire les cultistes un par un. Trop dur ? Passe l'étape : la suite de la chaîne sera sautée.", en = "Blackchar Cave (west): 1 Symbol of Ragnaros from the Twilight cultists. Twilight Fire Guards are elite and Flamebringers (55-60) roam nearby: pull the cultists one at a time. Too hard? Skip the step: the rest of the chain will be skipped." },
      { t = "turnin", id = 3452, quest = "The Flame's Casing", lvl = 50, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade.", en = "Kalaran Windblade." },
      { t = "accept", id = 3453, quest = "The Torch of Retribution", lvl = 50, req = 40, pre = { 3452 }, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade : The Torch of Retribution.", en = "Kalaran Windblade: The Torch of Retribution." },
      { t = "do", id = 3453, quest = "The Torch of Retribution", lvl = 50, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Attends que Kalaran finisse la Torch of Retribution.", en = "Wait for Kalaran to finish the Torch of Retribution." },
      { t = "turnin", id = 3453, quest = "The Torch of Retribution", lvl = 50, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade.", en = "Kalaran Windblade." },
      { t = "accept", id = 3454, quest = "The Torch of Retribution", lvl = 50, req = 40, pre = { 3453 }, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade : prends la Torch of Retribution.", en = "Kalaran Windblade: take the Torch of Retribution." },
      { t = "turnin", id = 3454, quest = "The Torch of Retribution", lvl = 50, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39.1, text = "Kalaran Windblade.", en = "Kalaran Windblade." },
      { t = "accept", id = 3462, quest = "Squire Maltrake", lvl = 50, req = 40, pre = { 3454 }, zone = "Searing Gorge", m = 1427, x = 39.1, y = 39, text = "Kalaran Windblade : Squire Maltrake.", en = "Kalaran Windblade: Squire Maltrake." },
      { t = "turnin", id = 3462, quest = "Squire Maltrake", lvl = 50, zone = "Searing Gorge", m = 1427, x = 39.2, y = 39, text = "Squire Maltrake, juste à côté.", en = "Squire Maltrake, right next to him." },
      { t = "accept", id = 3463, quest = "Set Them Ablaze!", lvl = 52, req = 40, pre = { 3462 }, zone = "Searing Gorge", m = 1427, x = 39.2, y = 39, text = "Squire Maltrake : Set Them Ablaze!.", en = "Squire Maltrake: Set Them Ablaze!." },
      { t = "do", id = 3463, quest = "Set Them Ablaze!", lvl = 52, zone = "Searing Gorge", m = 1427, x = 34.5, y = 57.6, text = "Les 4 tours de garde (nord, sud, est, ouest) autour de The Cauldron : entre dans chacune et utilise la Torch of Retribution.", en = "The 4 sentry towers (north, south, east, west) around The Cauldron: go inside each and use the Torch of Retribution." },
      { t = "turnin", id = 3463, quest = "Set Them Ablaze!", lvl = 52, zone = "Searing Gorge", m = 1427, x = 39.2, y = 39, text = "Squire Maltrake.", en = "Squire Maltrake." },
      { t = "accept", id = 3481, quest = "Trinkets...", lvl = 50, req = 40, pre = { 3463 }, zone = "Searing Gorge", m = 1427, x = 38.9, y = 39, text = "Squire Maltrake : Trinkets....", en = "Squire Maltrake: Trinkets...." },
      { t = "turnin", id = 3481, quest = "Trinkets...", lvl = 50, zone = "Searing Gorge", m = 1427, x = 38.9, y = 39, text = "Ouvre le coffre près de Kalaran. Garde la Black Dragonflight Molt : elle vaut une quête à Cyrus (Burning Steppes, niveau 52).", en = "Open the chest near Kalaran. Keep the Black Dragonflight Molt: it is worth a quest from Cyrus (Burning Steppes, level 52)." },
      { t = "go", zone = "Searing Gorge", m = 1427, x = 34.8, y = 83.8, text = "Descends au sud jusqu'à Blackrock Mountain et traverse-la vers les Burning Steppes (ne prends pas l'entrée des donjons).", en = "Ride south to Blackrock Mountain and cross it to the Burning Steppes (don't take the dungeon entrances)." },
      { t = "level", level = 50, text = "Niveau 50 requis pour les prochaines quêtes. Tue les monstres du coin (ou fais un donjon) ; tu peux aussi passer cette étape pour sauter ces quêtes.", en = "Level 50 required for the next quests. Kill the local mobs (or run a dungeon); you can also skip this step to skip those quests." },
      { t = "accept", id = { 4296, 4726 }, quest = "Tablet of the Seven + Broodling Essence", lvl = 52, req = 50, zone = "Burning Steppes", m = 1428, x = 65.2, y = 23.9, text = "Flame Crest (à l'est de Blackrock Mountain) : Maxwort Uberglint (Tablet of the Seven) et Tinkee Steamboil juste à côté (Broodling Essence). Prends le point de vol.", en = "Flame Crest (east of Blackrock Mountain): Maxwort Uberglint (Tablet of the Seven) and Tinkee Steamboil right next to him (Broodling Essence). Grab the flight path." },
      { t = "do", id = 4296, quest = "Tablet of the Seven", lvl = 50, zone = "Burning Steppes", m = 1428, x = 54.1, y = 40.8, text = "Centre : recopie la Tablet of the Seven (la stèle). Des monstres de niveau 58-60 sont un peu à l'ouest : arrive par l'est.", en = "Centre: copy the Tablet of the Seven (the stone). Level 58-60 mobs are a bit to the west: come in from the east." },
      { t = "turnin", id = 3821, quest = "Dreadmaul Rock", lvl = 52, zone = "Burning Steppes", m = 1428, x = 80, y = 45.4, text = "Dreadmaul Rock (est) : la piste de Sha'ni Proudtusk.", en = "Dreadmaul Rock (east): Sha'ni Proudtusk's trail." },
      { t = "accept", id = 3822, quest = "Krom'Grul", lvl = 53, req = 48, pre = { 3821 }, zone = "Burning Steppes", m = 1428, x = 80, y = 45.4, text = "Sha'ni Proudtusk : Krom'Grul.", en = "Sha'ni Proudtusk: Krom'Grul." },
      { t = "do", id = 3822, quest = "Krom'Grul", lvl = 53, zone = "Burning Steppes", m = 1428, x = 79.7, y = 47.4, text = "Dreadmaul Rock : l'anneau de nez sur Krom'Grul (il passe d'une grotte à l'autre).", en = "Dreadmaul Rock: the nose ring from Krom'Grul (he moves between the caves)." },
      { t = "do", id = 4726, quest = "Broodling Essence", lvl = 52, zone = "Burning Steppes", m = 1428, x = 86.7, y = 31.2, text = "Nord-est : 8 Broodling Essences sur les dragonnets (utilise la fiole de Tinkee).", en = "Northeast: 8 Broodling Essences from the whelps (use Tinkee's flask)." },
      { t = "turnin", id = { 4296, 4726 }, quest = "Tablet of the Seven + Broodling Essence", lvl = 52, zone = "Burning Steppes", m = 1428, x = 65.2, y = 23.9, text = "Flame Crest : Maxwort Uberglint et Tinkee Steamboil.", en = "Flame Crest: Maxwort Uberglint and Tinkee Steamboil." },
      { t = "accept", id = 4808, quest = "Felnok Steelspring", lvl = 54, req = 50, pre = { 4726 }, zone = "Burning Steppes", m = 1428, x = 65.2, y = 24, text = "Tinkee Steamboil : Felnok Steelspring (une lettre pour Everlook, Winterspring : garde-la).", en = "Tinkee Steamboil: Felnok Steelspring (a letter for Everlook, Winterspring: keep it)." },
      { t = "go", zone = "Swamp of Sorrows", m = 1435, x = 46.1, y = 54.8, text = "À cheval jusqu'à Stonard (pas de vol : tu n'as pas encore ce point) : descends vers Redridge (contourne Lakeshire), passe à Duskwood par Three Corners (contourne Darkshire), puis à l'est par Deadwind Pass jusqu'à Swamp of Sorrows. Prends le point de vol de Stonard.", en = "Ride to Stonard (no flight: you don't have that point yet): go down into Redridge (around Lakeshire), into Duskwood through Three Corners (around Darkshire), then east through Deadwind Pass into Swamp of Sorrows. Grab the Stonard flight path." },
      { t = "accept", id = { 2581, 2583, 2585, 2601, 2603 }, quest = "Snickerfang Jowls + A Boar's Vitality + The Decisive Striker + The Basilisk's Bite + Vulture's Vigor", lvl = 50, req = 45, zone = "Blasted Lands", m = 1419, x = 50.5, y = 14.2, text = "Descends au sud dans les Blasted Lands : Bloodmage Drazial et Bloodmage Lynnore : les 5 quêtes de collecte.", en = "Ride south into the Blasted Lands: Bloodmage Drazial and Bloodmage Lynnore: the 5 collection quests." },
      { t = "accept", id = { 2521, 3501 }, quest = "To Serve Kum'isha + Everything Counts In Large Amounts", lvl = 55, req = 45, zone = "Blasted Lands", m = 1419, x = 52, y = 35.6, text = "Kum'isha the Collector : Plus au sud : To Serve Kum'isha et Everything Counts In Large Amounts.", en = "Kum'isha the Collector: Further south: To Serve Kum'isha and Everything Counts In Large Amounts." },
      { t = "do", id = { 2581, 2583, 2585, 2601, 2603 }, quest = "Snickerfang Jowls + A Boar's Vitality + The Decisive Striker + The Basilisk's Bite + Vulture's Vigor", lvl = 50, zone = "Blasted Lands", m = 1419, x = 49.7, y = 36.4, text = "Toute la zone (totaux pour les 5 quêtes) : 5 Snickerfang Jowls (hyènes), 6 Blasted Boar Lungs (sangliers), 6 Scorpok Pincers (scorpoks), 11 Basilisk Brains (basilics Redstone) et 14 Vulture Gizzards (vautours). Garde les Draenethyst Fragments et une Flawless Draenethyst Sphere si elle tombe.", en = "The whole zone (totals for the 5 quests): 5 Snickerfang Jowls (hyenas), 6 Blasted Boar Lungs (boars), 6 Scorpok Pincers (scorpoks), 11 Basilisk Brains (Redstone basilisks) and 14 Vulture Gizzards (vultures). Keep the Draenethyst Fragments and a Flawless Draenethyst Sphere if one drops." },
      { t = "turnin", id = { 2521, 3501 }, quest = "To Serve Kum'isha + Everything Counts In Large Amounts", lvl = 55, optional = true, zone = "Blasted Lands", m = 1419, x = 52, y = 35.6, text = "Kum'isha the Collector : rends ce que tu as (un Draenethyst Fragment, la sphère si elle est tombée). Pas de sphère ? Ne la farme pas : elle est rare.", en = "Kum'isha the Collector: turn in what you have (a Draenethyst Fragment, the sphere if it dropped). No sphere? Don't farm it: it's rare." },
      { t = "accept", id = 2522, quest = "Kum'isha's Endeavors", lvl = 55, req = 45, pre = { 2521 }, optional = true, zone = "Blasted Lands", m = 1419, x = 52, y = 35.6, text = "Kum'isha the Collector : Kum'isha's Endeavors, seulement si tu as déjà une 2e sphère.", en = "Kum'isha the Collector: Kum'isha's Endeavors, only if you already have a 2nd sphere." },
      { t = "turnin", id = 2522, quest = "Kum'isha's Endeavors", lvl = 55, optional = true, zone = "Blasted Lands", m = 1419, x = 52, y = 35.6, text = "Kum'isha the Collector.", en = "Kum'isha the Collector." },
      { t = "turnin", id = { 2581, 2583, 2585, 2601, 2603 }, quest = "Snickerfang Jowls + A Boar's Vitality + The Decisive Striker + The Basilisk's Bite + Vulture's Vigor", lvl = 50, zone = "Blasted Lands", m = 1419, x = 50.5, y = 14.2, text = "Bloodmage Drazial et Bloodmage Lynnore (nord).", en = "Bloodmage Drazial and Bloodmage Lynnore (north)." },
      { t = "level", level = 52, text = "Vise le niveau 52 avant de repartir : il est requis pour les dernières quêtes (Kargath, Cyrus) et pour Western Plaguelands. Il te manque un peu ? Continue sur les monstres des Blasted Lands.", en = "Aim for level 52 before leaving: it is required for the last quests (Kargath, Cyrus) and for the Western Plaguelands. A bit short? Keep killing Blasted Lands mobs." },
      { t = "turnin", id = 3822, quest = "Krom'Grul", lvl = 53, zone = "Badlands", m = 1418, x = 3.4, y = 48.1, text = "Thal'trak Proudtusk : Vole de Stonard vers Kargath : Krom'Grul — 40 m au sud de l'auberge.", en = "Thal'trak Proudtusk: Fly from Stonard to Kargath: Krom'Grul — 40 m south of the inn." },
