    steps = {
      { t = "note", text = "Guide Silithus (58-60), optionnel si tu es déjà 60. D'Everlook, vol vers Cenarion Hold (via Orgrimmar ou Gadgetzan). Base : Cenarion Hold. Prends le point de vol et lie ta pierre de foyer.", en = "Silithus guide (58-60), optional if you are already 60. From Everlook, fly to Cenarion Hold (via Orgrimmar or Gadgetzan). Base: Cenarion Hold. Grab the flight path and set your hearthstone." },
      { t = "note", text = "Avertissement PvP (risque élevé) : Cenarion Hold est partage, et la zone est pleine de joueurs 60. Reste près des gardes, garde ta pierre de foyer prête, et évite de te battre près des points chauds.", en = "PvP warning (high risk): Cenarion Hold is shared, and the zone is full of level-60 players. Stay near the guards, keep your hearthstone ready, and avoid fighting near the hotspots." },
      { t = "level", level = 56, text = "Niveau 56 conseillé pour cette zone. Si tu es en dessous, tue des monstres en chemin ou fais un donjon.", en = "Level 56 recommended for this zone. If you are below it, kill mobs on the way or run a dungeon." },
